      createdAt: '2024-01-01T00:15:00.000Z',
      updatedAt: '2024-01-01T00:15:00.000Z',
    });
    const patient1Record1Updated = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 130,
      measuredAt: '2024-01-01T01:00:00.000Z',
      createdAt: '2024-01-01T00:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const patient1Record2Deleted = createRecord({
      id: 'record-3',
      patientId: 'patient-1',
      glucoseValue: 92,
      measuredAt: '2024-01-01T02:00:00.000Z',
      createdAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:30:00.000Z',
