import { describe, expect, it } from 'vitest';

import { GlucoseRecordHistoryService } from './history-service';
import type { GlucoseRecord } from './types';
import type { GlucoseRecordHistoryEvent } from './history-types';

/**
 * Creates a glucose record fixture.
 *
 * @param overrides - Properties to override on the default record.
 * @returns A glucose record fixture.
 */
function createRecord(overrides: Partial<GlucoseRecord> = {}): GlucoseRecord {
  return {
    id: 'record-1',
    patientId: 'patient-1',
    measuredAt: '2024-01-01T00:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
    ...overrides,
  };
}

/**
 * Extracts the event actions from a list of history events.
 *
 * @param events - The history events.
 * @returns The event actions.
 */
function eventActions(events: GlucoseRecordHistoryEvent[]): Array<'created' | 'updated' | 'deleted'> {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action);
}

/**
 * Extracts the event record ids from a list of history events.
 *
 * @param events - The history events.
 * @returns The event record ids.
 */
function eventRecordIds(events: GlucoseRecordHistoryEvent[]): string[] {
  return events.map((event: GlucoseRecordHistoryEvent) => event.recordId);
}

describe('GlucoseRecordHistoryService', () => {
  it('appendCreated/appendUpdated/appendDeleted add events', async () => {
    const service = new GlucoseRecordHistoryService();

    const created = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const updatedBefore = created;
    const updatedAfter = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 125,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const deleted = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 90,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(created);
    service.appendUpdated(updatedBefore, updatedAfter);
    service.appendDeleted(deleted);

    const record1Events = await service.listByRecordId('record-1');
    const record2Events = await service.listByRecordId('record-2');
    const allEvents = await service.listAll('patient-1');

    expect(record1Events).toHaveLength(2);
    expect(eventActions(record1Events)).toEqual(['created', 'updated']);
    expect(record1Events[0]?.snapshot).toEqual(created);
    expect(record1Events[1]?.snapshot).toEqual(updatedAfter);

    expect(record2Events).toHaveLength(1);
    expect(eventActions(record2Events)).toEqual(['deleted']);
    expect(record2Events[0]?.snapshot).toEqual(deleted);

    expect(allEvents).toHaveLength(3);
    expect(eventActions(allEvents)).toEqual(['created', 'updated', 'deleted']);
    expect(eventRecordIds(allEvents)).toEqual(['record-1', 'record-1', 'record-2']);
  });

  it('listByRecordId returns only the matching record events', async () => {
    const service = new GlucoseRecordHistoryService();

    const record1Created = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const record2Created = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 88,
      measuredAt: '2024-01-01T00:30:00.000Z',
      updatedAt: '2024-01-01T00:30:00.000Z',
    });
    const record1Updated = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 110,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const record2Deleted = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 88,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(record1Created);
    service.appendCreated(record2Created);
    service.appendUpdated(record1Created, record1Updated);
    service.appendDeleted(record2Deleted);

    const record1Events = await service.listByRecordId('record-1');

    expect(record1Events).toHaveLength(2);
    expect(eventRecordIds(record1Events)).toEqual(['record-1', 'record-1']);
    expect(eventActions(record1Events)).toEqual(['created', 'updated']);
    expect(record1Events[0]?.snapshot).toEqual(record1Created);
    expect(record1Events[1]?.snapshot).toEqual(record1Updated);
  });

  it('listAll(patientId) returns events for a patient in insertion order', async () => {
    const service = new GlucoseRecordHistoryService();

    const patient1Record1Created = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const patient2RecordCreated = createRecord({
      id: 'record-2',
      patientId: 'patient-2',
      glucoseValue: 150,
      measuredAt: '2024-01-01T00:10:00.000Z',
      updatedAt: '2024-01-01T00:10:00.000Z',
    });
    const patient1Record1Updated = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 115,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const patient1Record3Deleted = createRecord({
      id: 'record-3',
      patientId: 'patient-1',
      glucoseValue: 92,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(patient1Record1Created);
    service.appendCreated(patient2RecordCreated);
    service.appendUpdated(patient1Record1Created, patient1Record1Updated);
    service.appendDeleted(patient1Record3Deleted);

    const patient1Events = await service.listAll('patient-1');

    expect(patient1Events).toHaveLength(3);
    expect(eventRecordIds(patient1Events)).toEqual(['record-1', 'record-1', 'record-3']);
    expect(eventActions(patient1Events)).toEqual(['created', 'updated', 'deleted']);
    expect(patient1Events[0]?.snapshot).toEqual(patient1Record1Created);
    expect(patient1Events[1]?.snapshot).toEqual(patient1Record1Updated);
    expect(patient1Events[2]?.snapshot).toEqual(patient1Record3Deleted);
  });

  it('preserves snapshots when supplied', async () => {
    const service = new GlucoseRecordHistoryService();

    const created = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      note: 'initial reading',
    });
    const updated = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 130,
      note: 'adjusted reading',
      measuredAt: '2024-01-01T01:30:00.000Z',
      updatedAt: '2024-01-01T01:30:00.000Z',
    });
    const deleted = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 130,
      note: 'adjusted reading',
      measuredAt: '2024-01-01T01:30:00.000Z',
      updatedAt: '2024-01-01T01:30:00.000Z',
    });

    service.appendCreated(created);
    service.appendUpdated(created, updated);
    service.appendDeleted(deleted);

    const events = await service.listByRecordId('record-1');

    expect(events).toHaveLength(3);
    expect(events[0]?.snapshot).toEqual(created);
    expect(events[1]?.snapshot).toEqual(updated);
    expect(events[2]?.snapshot).toEqual(deleted);
  });
});

