import { describe, expect, it } from 'vitest';

import { GlucoseRecordHistoryService } from './history-service';
import type { GlucoseRecord } from './types';
import type { GlucoseRecordHistoryEvent } from './history-types';

/**
 * Creates a glucose record fixture.
 *
 * @param overrides - Properties to override on the default record.
 * @returns A glucose record fixture.
 */
function createRecord(overrides: Partial<GlucoseRecord> = {}): GlucoseRecord {
  return {
    id: 'record-1',
    patientId: 'patient-1',
    measuredAt: '2024-01-01T00:00:00.000Z',
    glucoseValue: 100,
    unit: 'mg/dL',
    createdAt: '2024-01-01T00:00:00.000Z',
    updatedAt: '2024-01-01T00:00:00.000Z',
    ...overrides,
  };
}

/**
 * Extracts the event actions from a list of history events.
 *
 * @param events - The history events.
 * @returns The event actions.
 */
function eventActions(events: GlucoseRecordHistoryEvent[]): Array<'created' | 'updated' | 'deleted'> {
  return events.map((event: GlucoseRecordHistoryEvent) => event.action);
}

describe('GlucoseRecordHistoryService', () => {
  it('appendCreated/appendUpdated/appendDeleted add events', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const updatedBefore: GlucoseRecord = created;
    const updatedAfter: GlucoseRecord = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 125,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const deleted: GlucoseRecord = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 90,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(created);
    service.appendUpdated(updatedBefore, updatedAfter);
    service.appendDeleted(deleted);

    const record1Events: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-1');
    const record2Events: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-2');
    const allEvents: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');

    expect(record1Events).toHaveLength(2);
    expect(eventActions(record1Events)).toEqual(['created', 'updated']);
    expect(record1Events[0]?.snapshot).toBe(created);
    expect(record1Events[1]?.snapshot).toBe(updatedAfter);

    expect(record2Events).toHaveLength(1);
    expect(eventActions(record2Events)).toEqual(['deleted']);
    expect(record2Events[0]?.snapshot).toBe(deleted);

    expect(allEvents).toHaveLength(3);
    expect(eventActions(allEvents)).toEqual(['created', 'updated', 'deleted']);
  });

  it("listByRecordId returns only the matching record's events", async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const record1Created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const record1Updated: GlucoseRecord = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 110,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const record2Created: GlucoseRecord = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 130,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(record1Created);
    service.appendUpdated(record1Created, record1Updated);
    service.appendCreated(record2Created);

    const record1Events: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-1');

    expect(record1Events).toHaveLength(2);
    expect(record1Events.every((event: GlucoseRecordHistoryEvent) => event.recordId === 'record-1')).toBe(true);
    expect(eventActions(record1Events)).toEqual(['created', 'updated']);
    expect(record1Events[0]?.snapshot).toBe(record1Created);
    expect(record1Events[1]?.snapshot).toBe(record1Updated);
  });

  it('listAll(patientId) returns events for a patient in insertion order', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const patient1Record1Created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const patient2RecordCreated: GlucoseRecord = createRecord({
      id: 'record-2',
      patientId: 'patient-2',
      glucoseValue: 140,
      measuredAt: '2024-01-01T00:30:00.000Z',
      updatedAt: '2024-01-01T00:30:00.000Z',
    });
    const patient1Record1Updated: GlucoseRecord = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 115,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const patient1Record3Deleted: GlucoseRecord = createRecord({
      id: 'record-3',
      patientId: 'patient-1',
      glucoseValue: 95,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(patient1Record1Created);
    service.appendCreated(patient2RecordCreated);
    service.appendUpdated(patient1Record1Created, patient1Record1Updated);
    service.appendDeleted(patient1Record3Deleted);

    const patient1Events: GlucoseRecordHistoryEvent[] = await service.listAll('patient-1');

    expect(patient1Events).toHaveLength(3);
    expect(patient1Events.map((event: GlucoseRecordHistoryEvent) => event.recordId)).toEqual([
      'record-1',
      'record-1',
      'record-3',
    ]);
    expect(eventActions(patient1Events)).toEqual(['created', 'updated', 'deleted']);
  });

  it('preserves snapshots when supplied', async () => {
    const service: GlucoseRecordHistoryService = new GlucoseRecordHistoryService();

    const created: GlucoseRecord = createRecord({ id: 'record-1', patientId: 'patient-1' });
    const updated: GlucoseRecord = createRecord({
      id: 'record-1',
      patientId: 'patient-1',
      glucoseValue: 150,
      measuredAt: '2024-01-01T01:00:00.000Z',
      updatedAt: '2024-01-01T01:00:00.000Z',
    });
    const deleted: GlucoseRecord = createRecord({
      id: 'record-2',
      patientId: 'patient-1',
      glucoseValue: 88,
      measuredAt: '2024-01-01T02:00:00.000Z',
      updatedAt: '2024-01-01T02:00:00.000Z',
    });

    service.appendCreated(created);
    service.appendUpdated(created, updated);
    service.appendDeleted(deleted);

    const createdEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-1');
    const deletedEvents: GlucoseRecordHistoryEvent[] = await service.listByRecordId('record-2');

    expect(createdEvents[0]?.snapshot).toBe(created);
    expect(createdEvents[1]?.snapshot).toBe(updated);
    expect(deletedEvents[0]?.snapshot).toBe(deleted);
  });
});

